      "text": "In Alaska, you can request a crash report completed by law enforcement from the Division of Motor Vehicles (DMV) by sending DMV Form 440 by email or mail. The Department of Public Safety (DPS) also holds State Trooper Collision Reports, which you can request through its online records portal.",
