        {
          "text": "The agency can extend that by up to 10 more working days if it tells you within the first 10. It can do this only when certain circumstances listed in the rules apply, and only for the documents those circumstances affect.",
          "sources": [
            7
          ]
        },
        {
          "text": "If your request will involve fees, the time between the agency's notice about the fees and your arrangement to pay them does not count toward the 10 working days.",
          "sources": [
            7
          ]
        },
        {
          "text": "The agency must grant or deny a written request in writing within the time limit. If you get no answer by then, you may consider the request denied.",
          "sources": [
            7
          ]
        },
        {
          "text": "The Alaska Department of Law says you can appeal a denial to the head of the agency within 60 working days from the date the denial was issued.",
          "sources": [
            6
          ]
        }
